const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const SAFE_ID=/^[A-Za-z0-9._:-]{1,200}$/;
export function assertUuid(value,name){if(typeof value!=='string'||!UUID.test(value))throw new Error(`Invalid ${name}`);return value.toLowerCase();}
export function createRequestContext(input){const tenantId=assertUuid(input.tenantId,'tenantId');const principalId=assertUuid(input.principalId,'principalId');if(!SAFE_ID.test(input.requestId??''))throw new Error('Invalid requestId');if(!SAFE_ID.test(input.correlationId??''))throw new Error('Invalid correlationId');const permissions=Object.freeze([...new Set((input.permissions??[]).filter(x=>typeof x==='string'&&x.length>0))].sort());return Object.freeze({tenantId,principalId,requestId:input.requestId,correlationId:input.correlationId,permissions,domains:Object.freeze([...(input.domains??[])]),maxSensitivity:Number.isInteger(input.maxSensitivity)?input.maxSensitivity:0});}
export function authorizeTenantSelection({selectedTenantId,memberships}){const selected=assertUuid(selectedTenantId,'selectedTenantId');if(!Array.isArray(memberships)||!memberships.some(x=>x.tenantId?.toLowerCase()===selected&&x.active===true))throw new Error('Forbidden');return selected;}
export async function withTenantTransaction(pool,context,work){const client=await pool.connect();try{await client.query('BEGIN');await client.query("SELECT set_config('rva.tenant_id',$1,true),set_config('rva.principal_id',$2,true),set_config('rva.request_id',$3,true),set_config('rva.correlation_id',$4,true)",[context.tenantId,context.principalId,context.requestId,context.correlationId]);const result=await work(client);await client.query('COMMIT');return result;}catch(error){try{await client.query('ROLLBACK');}catch{}throw error;}finally{client.release();}}
